import{_ as r,o,c as t,a0 as i}from"./chunks/framework.DRjqbEpm.js";const g=JSON.parse('{"title":"❓ 常見問題 (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),e={name:"guide/faq.md"};function l(n,a,s,h,c,d){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="❓-常見問題-faq" tabindex="-1">❓ 常見問題 (FAQ) <a class="header-anchor" href="#❓-常見問題-faq" aria-label="Permalink to &quot;❓ 常見問題 (FAQ)&quot;">​</a></h1><p>遇到怪問題嗎？先看看這裡有沒有解答！找不到答案再去 <a href="https://github.com/vtrain-labs/v-train-extension/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 回報。</p><hr><h2 id="🔴-進度條相關問題" tabindex="-1">🔴 進度條相關問題 <a class="header-anchor" href="#🔴-進度條相關問題" aria-label="Permalink to &quot;🔴 進度條相關問題&quot;">​</a></h2><h3 id="q-為什麼我在某個影片網站上看不到紅色進度條" tabindex="-1">Q：為什麼我在某個影片網站上看不到紅色進度條？ <a class="header-anchor" href="#q-為什麼我在某個影片網站上看不到紅色進度條" aria-label="Permalink to &quot;Q：為什麼我在某個影片網站上看不到紅色進度條？&quot;">​</a></h3><p><strong>可能原因與解法（依序排查）：</strong></p><ol><li><p><strong>沒有授權這個網站</strong><br> → 打開控制面板，點擊 <strong>「授權並啟用(Authorize &amp; Enable Current Site)」</strong> 按鈕</p></li><li><p><strong>V-Train 不認識這個網站</strong><br> → 如果授權後還是沒出現，這個網站需要手動訓練。請去使用<a href="./adaptive-engine.html">適應引擎</a>訓練它！</p></li><li><p><strong>目前是「手動暫停(Monitoring Off)」模式</strong><br> → ✅ 確認控制面板的狀態開關是「🟢 <strong>自動監控(Monitoring)</strong>」，而不是「<strong>手動暫停(Monitoring Off)</strong>」。</p></li><li><p><strong>您在影片播放頁（不是列表頁）</strong><br> → V-Train 的進度條顯示在<strong>影片縮圖列表</strong>上。在播放頁面看不到是正常的，請回到列表頁確認。</p></li><li><p><strong>網頁需要重新整理</strong><br> → 授權後若沒有立刻出現進度條，請按 <strong>F5</strong> 重新整理網頁。</p></li></ol><hr><h3 id="q-為什麼有些影片的進度條消失了-免費版限制" tabindex="-1">Q：為什麼有些影片的進度條消失了？（免費版限制） <a class="header-anchor" href="#q-為什麼有些影片的進度條消失了-免費版限制" aria-label="Permalink to &quot;Q：為什麼有些影片的進度條消失了？（免費版限制）&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">免費版 200 筆上限</p><p>免費版最多記錄 <strong>200 筆</strong>影片進度。當超過 200 筆時，系統會自動刪除最久沒更新的紀錄。<br> 若要永久保存所有進度，請升級 <a href="./pro-features.html">Pro 版</a>。</p></div><p>如果是 Pro 版用戶，進度消失可能是您不小心清除了資料，或是備份還原時出錯，建議定期備份。</p><hr><h3 id="q-進度條的顏色怎麼改" tabindex="-1">Q：進度條的顏色怎麼改？ <a class="header-anchor" href="#q-進度條的顏色怎麼改" aria-label="Permalink to &quot;Q：進度條的顏色怎麼改？&quot;">​</a></h3><p>打開控制面板，找到 <strong>「Progress Bar Color（進度條顏色）」</strong> 的色塊，點擊它就能開啟顏色選擇器，選擇您喜歡的任何顏色！</p><hr><h2 id="🖼️-截圖相關問題" tabindex="-1">🖼️ 截圖相關問題 <a class="header-anchor" href="#🖼️-截圖相關問題" aria-label="Permalink to &quot;🖼️ 截圖相關問題&quot;">​</a></h2><h3 id="q-為什麼截圖按鈕上出現紅色-❌" tabindex="-1">Q：為什麼截圖按鈕上出現紅色 ❌？ <a class="header-anchor" href="#q-為什麼截圖按鈕上出現紅色-❌" aria-label="Permalink to &quot;Q：為什麼截圖按鈕上出現紅色 ❌？&quot;">​</a></h3><p>V-Train 使用了多種技術嘗試截圖，但某些情況下仍然會失敗：</p><div class="warning custom-block"><p class="custom-block-title">常見的截圖失敗原因</p><ul><li><strong>跨域 <code>&lt;iframe&gt;</code></strong>：影片被嵌套在來自不同網域的 iframe 裡（常見於嵌入式播放器）</li><li><strong>嚴格的 CORS/CSP 政策</strong>：網站設定了阻止截圖的安全標頭</li><li><strong>CANVAS 繪製受限</strong>：某些使用 DRM 保護的影片無法透過 canvas 截圖</li></ul></div><p>截圖失敗不影響其他功能。您仍然可以：</p><ul><li>把影片加入書籤（使用原本的封面）</li><li>繼續追蹤觀看進度</li></ul><hr><h3 id="q-我之前截取的封面圖消失了-怎麼辦" tabindex="-1">Q：我之前截取的封面圖消失了，怎麼辦？ <a class="header-anchor" href="#q-我之前截取的封面圖消失了-怎麼辦" aria-label="Permalink to &quot;Q：我之前截取的封面圖消失了，怎麼辦？&quot;">​</a></h3><p>截圖封面儲存在瀏覽器的 <strong>IndexedDB</strong> 中。如果您有過下列操作，封面圖會消失：</p><ul><li>移除並重新安裝擴充功能</li><li>清除瀏覽器儲存資料</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 如何防止這個問題？</p><p>定期到控制面板執行<strong>匯出備份（Export Full Backup）</strong>，選擇「含截圖封面」選項，這樣您的封面圖就會一起被打包到 ZIP 備份中！</p></div><hr><h2 id="📕-書籤庫相關問題" tabindex="-1">📕 書籤庫相關問題 <a class="header-anchor" href="#📕-書籤庫相關問題" aria-label="Permalink to &quot;📕 書籤庫相關問題&quot;">​</a></h2><h3 id="q-書籤庫的封面圖過幾天就不見了-怎麼辦" tabindex="-1">Q：書籤庫的封面圖過幾天就不見了，怎麼辦？ <a class="header-anchor" href="#q-書籤庫的封面圖過幾天就不見了-怎麼辦" aria-label="Permalink to &quot;Q：書籤庫的封面圖過幾天就不見了，怎麼辦？&quot;">​</a></h3><p>這是「CDN 防盜鏈」問題，非常常見！<br> 許多影片網站的封面圖使用 CDN 服務，這些 CDN 會检查請求的來源（Referer），如果來源不對就拒絕顯示。</p><p>V-Train 有內建<strong>動態防盜鏈學習引擎</strong>：</p><blockquote><p>每次您開啟書籤庫時，系統會掃描所有書籤的封面 URL，自動找出 CDN 網域，並請 <code>background.js</code> 建立動態的 <code>declarativeNetRequest</code> 規則，偽裝成正確的 Referer 標頭，讓圖片重新顯示。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">💡 解決步驟</p><ol><li>關閉並重新開啟書籤庫頁面</li><li>等待幾秒讓防盜鏈引擎運作</li><li>若圖片還是不顯示，嘗試重新截圖（用 📸 截圖功能），這樣圖片就直接存在本地，完全不受防盜鏈影響！</li></ol></div><hr><h3 id="q-我不小心刪除了一個書籤-能復原嗎" tabindex="-1">Q：我不小心刪除了一個書籤，能復原嗎？ <a class="header-anchor" href="#q-我不小心刪除了一個書籤-能復原嗎" aria-label="Permalink to &quot;Q：我不小心刪除了一個書籤，能復原嗎？&quot;">​</a></h3><p>很遺憾，書籤刪除後<strong>無法直接復原</strong>（除非您有備份）。<br> 這是因為 V-Train 採用零伺服器架構，沒有「回收站」或「雲端備份」功能。</p><div class="warning custom-block"><p class="custom-block-title">建議</p><ul><li>在刪除大量書籤前，先做一次<strong>備份（Export）</strong></li><li>可以把重要的書籤放在特定資料夾，避免誤刪</li></ul></div><hr><h2 id="🔐-密碼與隱私問題" tabindex="-1">🔐 密碼與隱私問題 <a class="header-anchor" href="#🔐-密碼與隱私問題" aria-label="Permalink to &quot;🔐 密碼與隱私問題&quot;">​</a></h2><h3 id="q-我忘記自己設定的密碼了" tabindex="-1">Q：我忘記自己設定的密碼了！ <a class="header-anchor" href="#q-我忘記自己設定的密碼了" aria-label="Permalink to &quot;Q：我忘記自己設定的密碼了！&quot;">​</a></h3><p>請參閱 <a href="./pro-features.html#忘記密碼怎麼辦">Pro 版進階功能</a> 的「忘記密碼救援」部分。</p><p>簡要步驟：在密碼輸入畫面點擊 <strong>「忘記密碼(Forgot Passcode?)」</strong> → 輸入您的 <strong>Pro 授權序號</strong> → 密碼重置。</p><hr><h3 id="q-v-train-有沒有把我的資料上傳到任何地方" tabindex="-1">Q：V-Train 有沒有把我的資料上傳到任何地方？ <a class="header-anchor" href="#q-v-train-有沒有把我的資料上傳到任何地方" aria-label="Permalink to &quot;Q：V-Train 有沒有把我的資料上傳到任何地方？&quot;">​</a></h3><p><strong>絕對沒有。</strong> V-Train 採用「零伺服器架構」：</p><ul><li>所有觀看紀錄、書籤、規則都只存在您的<strong>本機瀏覽器</strong>中</li><li>唯一的網路請求是 Pro 版<strong>授權序號驗證</strong>（僅傳送序號本身，不包含任何個人資料）</li><li>V-Train <strong>沒有自己的資料庫伺服器</strong></li></ul><p>您可以透過 Chrome 開發者工具的「網路」分頁自行驗證這一點。</p><hr><h3 id="q-如果我移除-v-train-我的資料還在嗎" tabindex="-1">Q：如果我移除 V-Train，我的資料還在嗎？ <a class="header-anchor" href="#q-如果我移除-v-train-我的資料還在嗎" aria-label="Permalink to &quot;Q：如果我移除 V-Train，我的資料還在嗎？&quot;">​</a></h3><p><strong>不在了！</strong> 移除擴充功能時，瀏覽器會一併清除該擴充功能的所有本地儲存資料，包含：</p><ul><li>IndexedDB 中的所有影片紀錄、書籤、截圖封面</li><li>chrome.storage.local 中的所有設定</li></ul><div class="danger custom-block"><p class="custom-block-title">⚠️ 移除前請先備份！</p><p>如果您有珍貴的書籤或截圖，在移除前請務必先執行<strong>匯出備份（Export Full Backup）</strong>！</p></div><hr><h2 id="🌐-適應引擎問題" tabindex="-1">🌐 適應引擎問題 <a class="header-anchor" href="#🌐-適應引擎問題" aria-label="Permalink to &quot;🌐 適應引擎問題&quot;">​</a></h2><h3 id="q-我訓練好了-但影片縮圖上還是沒有出現進度條" tabindex="-1">Q：我訓練好了，但影片縮圖上還是沒有出現進度條？ <a class="header-anchor" href="#q-我訓練好了-但影片縮圖上還是沒有出現進度條" aria-label="Permalink to &quot;Q：我訓練好了，但影片縮圖上還是沒有出現進度條？&quot;">​</a></h3><p>請依序排查：</p><ol><li><strong>確認訓練網站有被授權</strong>：控制面板 → 授權當前網站</li><li><strong>重新整理頁面</strong>：F5 或 Ctrl+R</li><li><strong>確認 Mod 存入了正確位置</strong>：控制面板 → 已訓練網站，確認有看到這個網站的規則</li><li><strong>確認框框選對了</strong>：訓練時應該選擇「包住縮圖的容器 div」，不能選圖片本身（IMG 標籤）</li></ol><p>若以上都沒問題，可能是這個網站的 URL 結構比較特殊。嘗試刪除舊規則，重新訓練，這次嘗試點擊 URL 中不同的分段作為 ID。</p><hr><h3 id="q-我的朋友給了我一個-vt-rule-z-序號-怎麼匯入" tabindex="-1">Q：我的朋友給了我一個 VT-RULE-Z... 序號，怎麼匯入？ <a class="header-anchor" href="#q-我的朋友給了我一個-vt-rule-z-序號-怎麼匯入" aria-label="Permalink to &quot;Q：我的朋友給了我一個 VT-RULE-Z... 序號，怎麼匯入？&quot;">​</a></h3><ol><li>開啟控制面板</li><li>點擊 <strong>「已訓練網站（已訓練網站(Trained Sites)）」</strong> 按鈕</li><li>在規則管理頁面，找到「匯入規則序號」輸入框</li><li>貼上 <code>VT-RULE-Z...</code> 序號，點擊確認</li><li>匯入成功後，此規則立刻生效！</li></ol><hr><h2 id="⚡-效能問題" tabindex="-1">⚡ 效能問題 <a class="header-anchor" href="#⚡-效能問題" aria-label="Permalink to &quot;⚡ 效能問題&quot;">​</a></h2><h3 id="q-v-train-會讓我的瀏覽器變慢嗎" tabindex="-1">Q：V-Train 會讓我的瀏覽器變慢嗎？ <a class="header-anchor" href="#q-v-train-會讓我的瀏覽器變慢嗎" aria-label="Permalink to &quot;Q：V-Train 會讓我的瀏覽器變慢嗎？&quot;">​</a></h3><p>V-Train 的設計非常注重效能：</p><ul><li>使用 <strong>IntersectionObserver</strong> 只追蹤畫面上可見的縮圖，不掃描整個 DOM</li><li>使用 <strong>MutationObserver</strong> 偵測頁面動態新增的元素，並做節流（debounce）</li><li>進度條繪製使用 <strong>requestAnimationFrame</strong> 批次處理，避免 Layout Thrashing</li><li>背景腳本使用節流鎖，防止高頻事件爆炸</li></ul><p>在一般使用情況下，對瀏覽器效能的影響<strong>幾乎可以忽略</strong>。</p><hr><h3 id="q-我同時開了很多書籤庫分頁-資料會不同步嗎" tabindex="-1">Q：我同時開了很多書籤庫分頁，資料會不同步嗎？ <a class="header-anchor" href="#q-我同時開了很多書籤庫分頁-資料會不同步嗎" aria-label="Permalink to &quot;Q：我同時開了很多書籤庫分頁，資料會不同步嗎？&quot;">​</a></h3><p>不會！V-Train 使用了 <strong>BroadcastChannel API (<code>vt_sync_channel</code>)</strong> 在所有開啟的書籤庫分頁之間即時同步。<br> 當您在一個書籤庫分頁新增或刪除書籤，其他所有分頁都會自動更新，無需手動重新整理。</p><hr><h2 id="🔔-無痕模式問題" tabindex="-1">🔔 無痕模式問題 <a class="header-anchor" href="#🔔-無痕模式問題" aria-label="Permalink to &quot;🔔 無痕模式問題&quot;">​</a></h2><h3 id="q-v-train-在無痕模式下可以用嗎" tabindex="-1">Q：V-Train 在無痕模式下可以用嗎？ <a class="header-anchor" href="#q-v-train-在無痕模式下可以用嗎" aria-label="Permalink to &quot;Q：V-Train 在無痕模式下可以用嗎？&quot;">​</a></h3><p>可以，但需要額外設定：</p><ol><li>在 Chrome 網址列輸入 <code>chrome://extensions/</code></li><li>找到 V-Train，點擊**「詳細資料」**</li><li>開啟**「在無痕視窗中啟用」**選項</li></ol><div class="info custom-block"><p class="custom-block-title">無痕模式的注意事項</p><p>V-Train 的 manifest 設定了 <code>&quot;incognito&quot;: &quot;spanning&quot;</code>，這表示在無痕模式下，V-Train 的資料與一般模式<strong>共用</strong>，不是分開的資料庫。<br> 在無痕視窗看過的影片，進度紀錄同樣會被記錄下來。</p></div><hr><h2 id="💬-還是找不到答案" tabindex="-1">💬 還是找不到答案？ <a class="header-anchor" href="#💬-還是找不到答案" aria-label="Permalink to &quot;💬 還是找不到答案？&quot;">​</a></h2><ol><li>去 <a href="https://github.com/vtrain-labs/v-train-extension/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 搜尋看看有沒有類似的問題</li><li>如果沒有，點擊 <strong>「New Issue」</strong> 建立一個新的問題回報，請描述： <ul><li>您的 Chrome 版本</li><li>V-Train 版本（在 <code>chrome://extensions/</code> 可以查看）</li><li>問題發生的網站（若可以公開）</li><li>重現步驟</li></ul></li></ol>',79)])])}const p=r(e,[["render",l]]);export{g as __pageData,p as default};
